from collections import Counter

# Count dialogs per company
company_counts = Counter(d['company_id'] for d in dataset)
print("Total dialogs per company:")
for company, count in company_counts.most_common():
    print(f"  {company}: {count}")

# Let's first do a keyword search to identify dialogs potentially about flight booking issues
booking_keywords = ['book', 'booking', 'reservation', 'reserve', 'cancel', 'reschedule', 
                    'change flight', 'modify', 'ticket', 'itinerary', 'confirmation']

def has_booking_keywords(dialog_text):
    lower_text = dialog_text.lower()
    return any(kw in lower_text for kw in booking_keywords)

# Count potential booking-related dialogs per company
booking_dialogs_by_company = {}
for d in dataset:
    company = d['company_id']
    if company not in booking_dialogs_by_company:
        booking_dialogs_by_company[company] = []
    if has_booking_keywords(d['dialog']):
        booking_dialogs_by_company[company].append(d)

print("\nDialogs with booking keywords per company:")
for company in sorted(booking_dialogs_by_company.keys()):
    print(f"  {company}: {len(booking_dialogs_by_company[company])}")
